import Button from '@jetbrains/ring-ui-built/components/button/button'
import {useCallback, memo} from 'react'

import {useBoolean} from '../../../../../hooks/useSlice'
import {noop} from '../../../../../utils/empty'
import httpsConfigurationApi from '../../HttpsConfigurationPage.api'
import {useDisplayErrorAlert} from '../../HttpsConfigurationPage.hooks'

import ConfirmationDialog from 'src/components/common/ConfirmationDialog/ConfirmationDialog'

function RemoveCertificateButton() {
  const [show, showDialog, hideDialog] = useBoolean(false)

  const [removeCertificate, {isLoading, error}] =
    httpsConfigurationApi.endpoints.removeCertificate.useMutation()

  const onConfirm = useCallback(() => {
    removeCertificate()
      .unwrap()
      .then(() => hideDialog(), noop)
  }, [removeCertificate, hideDialog])

  useDisplayErrorAlert(error)

  return (
    <>
      <Button onClick={showDialog} danger>
        {'Remove'}
      </Button>
      <ConfirmationDialog
        show={show}
        title={'Remove the installed certificate?'}
        confirmButtonText={'Remove'}
        loader={isLoading}
        onConfirm={onConfirm}
        onCancel={hideDialog}
      />
    </>
  )
}

export default memo(RemoveCertificateButton)
