import alertService from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import type {SerializedError} from '@reduxjs/toolkit'
import type {FetchBaseQueryError} from '@reduxjs/toolkit/query'
import {useEffect} from 'react'
import {graphql, useFragment} from 'react-relay'

import {useIsSakuraSelected} from '../../../hooks/useIsSakuraSelected'
import {extractError} from '../../../utils/extractError'

import type {HttpsConfigurationPageDomainInfoFragment$key} from './__generated__/HttpsConfigurationPageDomainInfoFragment.graphql'
import type {HttpsConfigurationPageServerUrlInfoFragment$key} from './__generated__/HttpsConfigurationPageServerUrlInfoFragment.graphql'

const DEFAULT_TIMEOUT = 3000

const domainInfoFragment = graphql`
  fragment HttpsConfigurationPageDomainInfoFragment on Server {
    webUrl
    artifactsUrl
  }
`

const serverUrlInfoFragment = graphql`
  fragment HttpsConfigurationPageServerUrlInfoFragment on Server {
    webUrl
  }
`

export const useDisplayErrorAlert = (
  error?: FetchBaseQueryError | SerializedError | string | null,
  timeout = DEFAULT_TIMEOUT,
) => {
  useEffect(() => {
    if (error != null) {
      alertService.error(
        typeof error === 'string' ? error : extractError(error)?.toString(),
        timeout,
      )
    }
  }, [error, timeout])
}

export const useAgentsParamsLink = (param: string) => {
  const classicUIAgentsParamsLink = '/agents.html?tab=agentsParametersReport'
  const sakuraUIAgentsParamsLink = '/agents/overview?tab=agentsParametersReport'
  const isSakuraSelected = useIsSakuraSelected()

  return resolveRelative(
    isSakuraSelected
      ? `${sakuraUIAgentsParamsLink}&iframeSrc=${encodeURIComponent(
          resolveRelative(`${classicUIAgentsParamsLink}&embedded=true#${param}`),
        )}`
      : `${classicUIAgentsParamsLink}#${param}`,
  )
}

const getDomainFromUrl = (url: string | null | undefined) => {
  if (url === '' || url == null) {
    return url
  }
  try {
    return new URL(url).hostname
  } catch {
    return null
  }
}
export const useDomainInfo = (
  serverInfoKey: HttpsConfigurationPageDomainInfoFragment$key | null,
) => {
  const {webUrl, artifactsUrl} = useFragment(domainInfoFragment, serverInfoKey) ?? {}
  return {serverDomain: getDomainFromUrl(webUrl), artifactsDomain: getDomainFromUrl(artifactsUrl)}
}

export const useServerUrlInfo = (
  serverInfoKey: HttpsConfigurationPageServerUrlInfoFragment$key | null,
) => {
  const {webUrl} = useFragment(serverUrlInfoFragment, serverInfoKey) ?? {}
  let url = null
  try {
    url = webUrl != null ? new URL(webUrl) : null
  } catch {
    // ignore
  }
  return {hostname: url?.hostname, origin: url?.origin}
}
