import Input, {Size} from '@jetbrains/ring-ui-built/components/input/input'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import * as React from 'react'

import styles from './PortConfiguration.module.css'

type Props = {
  className?: string
  value?: string
  error?: boolean
  placeholder?: string
  isLoading?: boolean
  onChange?: (e: React.ChangeEvent<HTMLInputElement>) => void
}

function PortConfiguration({className, value, error, placeholder, isLoading, onChange}: Props) {
  return (
    <div className={className}>
      <div>{'Port'}</div>
      <div className={styles.port}>
        <Input
          type={'number'}
          placeholder={placeholder}
          size={Size.AUTO}
          value={value}
          error={error ? '' : null}
          onChange={onChange}
          disabled={isLoading}
          autoComplete={'off'}
        />
        {isLoading && (
          <div>
            <LoaderInline />
          </div>
        )}
      </div>
      <div className={styles.error}>{error && 'Incorrect port number'}</div>
    </div>
  )
}

export default React.memo(PortConfiguration)
