import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {Header, Content} from '@jetbrains/ring-ui-built/components/island/island'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import classNames from 'classnames'
import {useState, useCallback, useEffect, memo} from 'react'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import type {HttpsConfigurationPageQuery} from '../../__generated__/HttpsConfigurationPageQuery.graphql'
import CertificateFetchForm from '../../CertificateInstallationForm/CertificateFetchForm/CertificateFetchForm'
import httpsConfigurationApi from '../../HttpsConfigurationPage.api'

import styles from './CertificateRenewal.module.css'

const EXPIRATION_THRESHOLD = 30

type Props = {
  daysBeforeExpiration: number
  fetchedFromAcme: boolean
  serverInfoQueryRef: PreloadedQuery<HttpsConfigurationPageQuery>
}
function CertificateRenewal({daysBeforeExpiration, fetchedFromAcme, serverInfoQueryRef}: Props) {
  const [displayDialog, setDisplayDialog] = useState(false)

  const [fetchCertificate, {isLoading}] =
    httpsConfigurationApi.endpoints.fetchCertificateFromAcme.useMutation()

  const shouldShowWarning = daysBeforeExpiration <= EXPIRATION_THRESHOLD
  const {data: pendingAcmeOrder} = httpsConfigurationApi.endpoints.getPendingAcmeOrder.useQuery(
    undefined,
    {skip: !fetchedFromAcme || !shouldShowWarning},
  )

  const onCloseAttempt = useCallback(() => setDisplayDialog(false), [])
  const handleRenewClick = useCallback(() => {
    if (pendingAcmeOrder != null) {
      setDisplayDialog(true)
      return
    }
    fetchCertificate(null)
      .unwrap()
      .then(() => setDisplayDialog(true))
  }, [pendingAcmeOrder, fetchCertificate])

  useEffect(() => {
    if (pendingAcmeOrder == null) {
      setDisplayDialog(false)
    }
  }, [pendingAcmeOrder])

  return shouldShowWarning ? (
    <>
      <div
        className={classNames(
          styles.expirationInfo,
          daysBeforeExpiration > 0 ? styles.warning : styles.expired,
          !fetchedFromAcme && styles.infoMargin,
        )}
      >
        <span>
          {daysBeforeExpiration > 0
            ? `The certificate will expire in ${
                daysBeforeExpiration > 1 ? `${daysBeforeExpiration} days` : 'less than a day'
              }.`
            : 'The certificate is expired.'}
        </span>
        {fetchedFromAcme && (
          <>
            <Link
              className={styles.renewalBtn}
              onClick={handleRenewClick}
              disabled={isLoading}
              pseudo
            >
              {'Renew'}
            </Link>
            {isLoading && <LoaderInline />}
            {displayDialog && (
              <Dialog
                contentClassName={styles.dialog}
                onCloseAttempt={onCloseAttempt}
                autoFocusFirst={false}
                showCloseButton
                closeButtonInside
                show
              >
                <Header>{'Certificate Renewal'}</Header>
                <Content scrollableWrapperClassName={styles.dialogContent}>
                  <CertificateFetchForm serverInfoQueryRef={serverInfoQueryRef} />
                </Content>
              </Dialog>
            )}
          </>
        )}
      </div>
    </>
  ) : null
}

export default memo(CertificateRenewal)
