import Button from '@jetbrains/ring-ui-built/components/button/button'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import {useEffect, useState} from 'react'
import {usePreloadedQuery} from 'react-relay'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import {useOnDemandQuery} from '../../../../../../hooks/relay/useOnDemandQuery'
import type {HttpsConfigurationPageQuery} from '../../../__generated__/HttpsConfigurationPageQuery.graphql'
import httpsConfigurationApi from '../../../HttpsConfigurationPage.api'
import {useDomainInfo} from '../../../HttpsConfigurationPage.hooks'
import {query} from '../../../HttpsConfigurationPage.queries'

import styles from './TermsOfServiceForm.module.css'

type DomainErrorProps = {
  type: 'server' | 'artifacts'
  isLocalhost?: boolean
}
function DomainError({type, isLocalhost}: DomainErrorProps) {
  return (
    <div className={styles.domainError}>
      <SvgIcon icon={'exception'} />
      {isLocalhost ? (
        <>
          {`The certificate cannot be issued for the ${type} domain `}
          <strong>{'localhost'}</strong>
        </>
      ) : (
        `Failed to resolve the ${type} domain`
      )}
      {'. '}
      {!isLocalhost && 'Consider '}
      <Link
        href={resolveRelative('/admin/admin.html?item=serverConfigGeneral')}
        target="_blank"
        rel="noreferrer"
      >
        {`${isLocalhost ? 'Change' : 'changing'} the ${type} URL`}
      </Link>
      {'.'}
    </div>
  )
}

// eslint-disable-next-line eqeqeq
const isDomainError = (domain?: string | null) => domain === 'localhost' || domain === null

type Props = {
  serverInfoQueryRef: PreloadedQuery<HttpsConfigurationPageQuery>
}
function TermsOfServiceForm({serverInfoQueryRef}: Props) {
  const data = usePreloadedQuery(query, serverInfoQueryRef)
  const refetch = useOnDemandQuery(query)
  const {serverDomain, artifactsDomain} = useDomainInfo(data.serverInfo ?? null)

  const isServerDomainError = isDomainError(serverDomain)
  const isArtifactsDomainError = isDomainError(artifactsDomain)

  const [isDomainInfoFetching, setIsDomainInfoFetching] = useState(false)

  useEffect(() => {
    const onChange = () => {
      if (document.visibilityState === 'visible') {
        setIsDomainInfoFetching(true)
        refetch(serverInfoQueryRef.variables, true)
          .toPromise()
          .finally(() => setIsDomainInfoFetching(false))
      }
    }
    document.addEventListener('visibilitychange', onChange)
    return () => document.removeEventListener('visibilitychange', onChange)
  })

  const {terms, areTermsFetching} = httpsConfigurationApi.endpoints.getTermsOfService.useQuery(
    undefined,
    {
      selectFromResult: ({currentData, isFetching}) => ({
        terms: currentData,
        areTermsFetching: isFetching,
      }),
      skip: isServerDomainError || isArtifactsDomainError,
    },
  )

  const [fetchCertificate, {isLoading: fetchCertificateLoading}] =
    httpsConfigurationApi.endpoints.fetchCertificateFromAcme.useMutation({
      fixedCacheKey: 'fetchCertificateFromAcme',
    })

  return (
    <div
      className={classNames(styles.termsContainer, {
        [styles.overlay]: isDomainInfoFetching || areTermsFetching,
      })}
    >
      {isServerDomainError || isArtifactsDomainError ? (
        <div className={styles.errorBlock}>
          {isServerDomainError && (
            <DomainError type={'server'} isLocalhost={serverDomain === 'localhost'} />
          )}
          {isArtifactsDomainError && (
            <DomainError type={'artifacts'} isLocalhost={artifactsDomain === 'localhost'} />
          )}
        </div>
      ) : (
        <>
          <div className={styles.domainInfo}>
            {'A certificate will be issued for the server domain '}
            <strong>{serverDomain}</strong>
            {'.'}
            {artifactsDomain !== '' && (
              <>
                <br />
                {'Additional certificate will be issued for the artifacts domain '}
                <strong>{artifactsDomain}</strong>
                {'.'}
              </>
            )}
          </div>
          <div className={styles.terms}>
            {terms != null && (
              <>
                {'Read the '}
                <Link href={terms} target="_blank" rel="noreferrer">
                  {`Terms of Service`}
                </Link>
                {'.'}
              </>
            )}
          </div>
          <Button
            onClick={fetchCertificate}
            loader={fetchCertificateLoading}
            disabled={terms == null}
            primary
          >
            {'Agree and fetch'}
          </Button>
        </>
      )}
    </div>
  )
}

export default TermsOfServiceForm
