import ButtonSet from '@jetbrains/ring-ui-built/components/button-set/button-set'
import moment from 'moment'
import {Suspense, useMemo} from 'react'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import type {HttpsConfigurationPageQuery} from '../__generated__/HttpsConfigurationPageQuery.graphql'
import {useDisplayErrorAlert} from '../HttpsConfigurationPage.hooks'
import type {Certificate} from '../HttpsConfigurationPage.types'

import CertificateRenewal from './CertificateRenewal/CertificateRenewal'
import ConnectorSettings from './ConnectorSettings/ConnectorSettings'
import RemoveCertificateButton from './RemoveCertificateButton/RemoveCertificateButton'
import UploadCertificateButton from './UploadCertificateButton/UploadCertificateButton'

import styles from './CertificateInfo.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

const dateFormat = 'D MMM YYYY, HH:mm'

type Props = Certificate & {
  serverInfoQueryRef: PreloadedQuery<HttpsConfigurationPageQuery>
}

function CertificateInfo({
  subject,
  issuer,
  notBefore,
  notAfter,
  fetchedFromAcme,
  connector,
  serverInfoQueryRef,
}: Props) {
  // const serverInfo = useFragment(serverInfoFragment, serverInfoKey)
  const notBeforeDate = useMemo(() => moment.utc(notBefore), [notBefore])
  const notAfterDate = useMemo(() => moment.utc(notAfter), [notAfter])
  const daysBeforeExpiration = useMemo(
    () => Math.ceil(moment.duration(notAfterDate.diff(moment.utc())).asDays()),
    [notAfterDate],
  )

  const error = useAppSelector(state => state.https.error)
  useDisplayErrorAlert(error)

  return (
    <>
      <div className={styles.info}>
        <div>{'Subject'}</div>
        <div>{subject}</div>
        <div>{'Issuer'}</div>
        <div>{issuer}</div>
        <div>{'Validity Period'}</div>
        <div>{`${notBeforeDate.format(dateFormat)} GMT - ${notAfterDate.format(
          dateFormat,
        )} GMT`}</div>
      </div>
      <ButtonSet>
        <UploadCertificateButton />
        <RemoveCertificateButton />
      </ButtonSet>
      {fetchedFromAcme && (
        <div className={styles.caption}>
          {"The certificate is fetched from Let's Encrypt. It will be revoked on removal."}
        </div>
      )}
      <CertificateRenewal
        daysBeforeExpiration={daysBeforeExpiration}
        fetchedFromAcme={fetchedFromAcme}
        serverInfoQueryRef={serverInfoQueryRef}
      />
      <Suspense>
        <ConnectorSettings {...connector} serverInfoQueryRef={serverInfoQueryRef} />
      </Suspense>
    </>
  )
}

export default CertificateInfo
