import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {Suspense} from 'react'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import type {HttpsConfigurationPageQuery} from '../../__generated__/HttpsConfigurationPageQuery.graphql'
import httpsConfigurationApi from '../../HttpsConfigurationPage.api'

import PendingAcmeOrderForm from './PendingAcmeOrderForm/PendingAcmeOrderForm'
import TermsOfServiceForm from './TermsOfServiceForm/TermsOfServiceForm'

import styles from './CertificateFetchForm.module.css'

type Props = {
  serverInfoQueryRef: PreloadedQuery<HttpsConfigurationPageQuery>
}
function CertificateFetchForm({serverInfoQueryRef}: Props) {
  const {data: pendingAcmeOrder} =
    httpsConfigurationApi.endpoints.getPendingAcmeOrder.useQueryState()

  return (
    <div className={styles.fetchForm}>
      {pendingAcmeOrder != null ? (
        <PendingAcmeOrderForm pendingAcmeOrder={pendingAcmeOrder} />
      ) : (
        <Suspense fallback={<LoaderInline>{'Loading...'}</LoaderInline>}>
          <TermsOfServiceForm serverInfoQueryRef={serverInfoQueryRef} />
        </Suspense>
      )}
    </div>
  )
}

export default CertificateFetchForm
