import * as React from 'react'

import {useBoolean} from '../../../../hooks/useSlice'

import PortConfiguration from './PortConfiguration'

const MIN_PORT_VALUE = 1
const MAX_PORT_VALUE = 65535

export const usePortConfiguration = (defaultPort = '443') => {
  const [value, setValue] = React.useState(defaultPort)
  const [error, showError, hideError] = useBoolean(false)

  React.useEffect(() => {
    setValue(defaultPort)
  }, [defaultPort])

  const onChange = React.useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      hideError()
      setValue(e.currentTarget.value)
    },
    [hideError],
  )

  const validate = React.useCallback(() => {
    const numValue = Number(value)

    if (
      value.length > 0 &&
      (!Number.isInteger(numValue) || numValue < MIN_PORT_VALUE || numValue > MAX_PORT_VALUE)
    ) {
      showError()
      return false
    }

    return true
  }, [value, showError])

  const portConfigurationProps = {
    value,
    error,
    onChange,
    placeholder: defaultPort,
  }

  return {
    value,
    error,
    validate,
    portConfigurationProps,
    PortConfiguration,
  }
}
